function OptimalVoiceLeading(source, target):
    best_cost <- infinity
    for each permutation sigma of {1,...,n}:
        cost <- sum_i d(source[i], target[sigma(i)])
        if cost < best_cost:
            best_cost <- cost; best_perm <- sigma
    return (best_cost, best_perm)

Complexity: O(n! * n) time, O(n) space
